using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using LighthouseKeepers.Core;using LighthouseKeepers.Gameplay.Interaction;
namespace LighthouseKeepers.WatchDemo {
 [DefaultExecutionOrder(1700)]public sealed class WorldWaterPresentation:MonoBehaviour {
  WatchPipeRepair pipe;Transform jet;Material jetMaterial,dropletMaterial;WatchDemoController watch;Transform head;Material flood,ocean,seepMaterial;Renderer sea,water;readonly List<Renderer> puddles=new();readonly List<Transform> contacts=new();readonly List<Transform> drift=new();MaterialPropertyBlock block;float nextRipple;int ripple;Mesh seaMesh;float nextSplash;AudioSource wash;ParticleSystem spray;
  public static void Create(WatchDemoController w){if(!VisualPassSettings.Current||!VisualPassSettings.Current.water)return;var p=w.gameObject.AddComponent<WorldWaterPresentation>();p.watch=w;}
  void Start(){head=Camera.main.transform;block=new MaterialPropertyBlock();flood=new Material(Resources.Load<Shader>("StormWater")){name="Flood dual ripple water"};flood.SetTexture("_NormalMap",Resources.Load<Texture2D>("WaterRippleNormal"));flood.SetColor("_BaseColor",new Color(.035f,.095f,.10f));ocean=new Material(flood){name="Ocean four wave surface"};ocean.SetFloat("_Ocean",1);ocean.SetColor("_BaseColor",new Color(.018f,.055f,.075f));
   var seaObject=GameObject.Find("Original storm ocean presentation");if(seaObject){sea=seaObject.GetComponent<Renderer>();sea.sharedMaterial=ocean;var filter=seaObject.GetComponent<MeshFilter>();if(filter){seaMesh=OceanMesh();filter.sharedMesh=seaMesh;seaObject.transform.SetPositionAndRotation(new Vector3(0,-1.1f,0),Quaternion.identity);seaObject.transform.localScale=Vector3.one;}}
   var w=GameObject.Find("Visible first-floor flood");if(w){water=w.GetComponent<Renderer>();water.sharedMaterial=flood;}foreach(var r in FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))if(r.transform.parent&&r.transform.parent.name=="House flood through tower doorway")r.sharedMaterial=flood;
   foreach(var hand in FindObjectsByType<HandRig>(FindObjectsSortMode.None))contacts.Add(hand.transform);contacts.Add(head);var tool=FindAnyObjectByType<WatchWrenchReturn>();if(tool)contacts.Add(tool.transform);
   for(int n=0;n<5;n++){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name="Nonblocking waterborne timber";go.transform.SetParent(transform,false);go.transform.position=new Vector3(Mathf.Sin(n*1.8f)*2.7f,0,Mathf.Cos(n*1.8f)*2.7f);go.transform.localScale=new Vector3(.24f,.035f,.10f);var c=go.GetComponent<Collider>();c.enabled=false;Destroy(c);go.GetComponent<Renderer>().sharedMaterial=Resources.Load<Material>("VisualMaterials/Wood");drift.Add(go.transform);}
   // Small patches spread through the entrance before the established volumetric House flood.
   for(int n=0;n<6;n++){var go=GameObject.CreatePrimitive(PrimitiveType.Cylinder);go.name="Doorway seep puddle";go.transform.SetParent(transform,false);go.transform.position=new Vector3((n%3-1)*.32f,.006f,-5.2f-(n/3)*.35f);go.transform.localScale=new Vector3(.04f,.002f,.04f);var c=go.GetComponent<Collider>();c.enabled=false;Destroy(c);var r=go.GetComponent<Renderer>();r.sharedMaterial=flood;r.shadowCastingMode=ShadowCastingMode.Off;puddles.Add(r);}
   pipe=FindAnyObjectByType<WatchPipeRepair>();jetMaterial=new Material(Resources.Load<Shader>("PracticalHaze"));jetMaterial.SetFloat("_Scroll",1);jetMaterial.SetColor("_BaseColor",new Color(.55f,.72f,.75f,.35f));var jetObject=GameObject.CreatePrimitive(PrimitiveType.Quad);jetObject.name="Pressurised active bolt water jet";jet=jetObject.transform;jet.SetParent(transform,false);var jc=jetObject.GetComponent<Collider>();jc.enabled=false;Destroy(jc);jetObject.GetComponent<Renderer>().sharedMaterial=jetMaterial;dropletMaterial=new Material(Resources.Load<Shader>("WaterSpray"));foreach(var drops in pipe.sprays){var main=drops.main;main.maxParticles=64;main.startSize=.014f;var renderer=drops.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=dropletMaterial;renderer.renderMode=ParticleSystemRenderMode.Stretch;renderer.lengthScale=1.2f;renderer.velocityScale=.018f;}
   seepMaterial=new Material(Resources.Load<Shader>("WallSeep"));for(int n=0;n<8;n++){var origin=new Vector3(0,.9f,0);var dir=Quaternion.Euler(0,n*45+15,0)*Vector3.forward;RaycastHit wall=default;float nearest=5;foreach(var hit in Physics.RaycastAll(origin,dir,5,~0,QueryTriggerInteraction.Ignore))if(hit.collider.name.Contains("Wall")&&hit.distance<nearest){wall=hit;nearest=hit.distance;}if(nearest>=5)continue;var go=GameObject.CreatePrimitive(PrimitiveType.Quad);go.name="Damp wall runoff";go.transform.SetParent(transform,false);go.transform.SetPositionAndRotation(wall.point+wall.normal*.015f,Quaternion.LookRotation(-wall.normal));go.transform.localScale=new Vector3(.45f,1.5f,1);var c=go.GetComponent<Collider>();c.enabled=false;Destroy(c);go.GetComponent<Renderer>().sharedMaterial=seepMaterial;}
   var burst=new GameObject("Rock impact spray");burst.transform.SetParent(transform,false);burst.transform.position=new Vector3(7,-.4f,3);spray=burst.AddComponent<ParticleSystem>();spray.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var sprayMain=spray.main;sprayMain.loop=false;sprayMain.playOnAwake=false;sprayMain.maxParticles=48;sprayMain.startLifetime=.7f;sprayMain.startSpeed=1.7f;sprayMain.startSize=.045f;sprayMain.gravityModifier=.5f;sprayMain.startColor=new Color(.6f,.75f,.78f,.3f);var emission=spray.emission;emission.rateOverTime=0;var shape=spray.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=25;burst.transform.rotation=Quaternion.Euler(-90,0,0);if(pipe.sprays.Length>0)spray.GetComponent<ParticleSystemRenderer>().sharedMaterial=pipe.sprays[0].GetComponent<ParticleSystemRenderer>().sharedMaterial;
   wash=new GameObject("Wave wash at inlet rocks").AddComponent<AudioSource>();wash.transform.SetParent(transform,false);wash.transform.position=new Vector3(7,-.5f,3);wash.playOnAwake=false;wash.spatialBlend=1;wash.minDistance=4;wash.maxDistance=25;wash.clip=Resources.Load<AudioClip>("S4Audio/water");KeeperAudioMix.Route(wash,"Ambience");
  }
  Mesh OceanMesh(){const int n=128;var v=new Vector3[(n+1)*(n+1)];var uv=new Vector2[v.Length];var tri=new int[n*n*6];for(int z=0;z<=n;z++)for(int x=0;x<=n;x++){int i=z*(n+1)+x;float px=(x/(float)n-.5f)*2,pz=(z/(float)n-.5f)*2;v[i]=new Vector3(Mathf.Sign(px)*px*px*160,0,Mathf.Sign(pz)*pz*pz*160);uv[i]=new Vector2(px,pz);if(x<n&&z<n){int t=(z*n+x)*6;tri[t]=i;tri[t+1]=i+n+1;tri[t+2]=i+1;tri[t+3]=i+1;tri[t+4]=i+n+1;tri[t+5]=i+n+2;}}var m=new Mesh{name="Ocean near-dense distant sparse 32k triangles"};m.vertices=v;m.uv=uv;m.triangles=tri;m.RecalculateNormals();m.bounds=new Bounds(Vector3.zero,new Vector3(325,8,325));return m;}
  void LateUpdate(){var s=watch.State;if(jet&&pipe){float strength=s.Pipe.InflowFraction;jet.gameObject.SetActive(!s.Repaired&&strength>.01f);var start=pipe.ActivePosition+Vector3.up*.06f;var end=start+Vector3.down*.65f+Vector3.left*.18f;jet.position=(start+end)*.5f;jet.rotation=Quaternion.LookRotation(Vector3.forward, (start-end).normalized);jet.localScale=new Vector3(.025f+strength*.04f,.3f+strength*.5f,1);}
float night=Mathf.Clamp01((s.Day-1)*.5f);float severity=Mathf.Max(night*.65f,(s.Storm.Stage-1)/3f);if(sea){sea.GetPropertyBlock(block);block.SetFloat("_StormAmplitude",Mathf.Lerp(.12f,.8f,severity));sea.SetPropertyBlock(block);}flood.SetFloat("_Night",s.Day);
   seepMaterial.SetFloat("_Wetness",Mathf.Lerp(.12f,.85f,night));float seep=Mathf.Clamp01((float)s.Elapsed/120)*Mathf.Lerp(.12f,1,night);foreach(var p in puddles){p.enabled=seep>.02f&&watch.WaterHeight<.015f;p.transform.localScale=new Vector3(.12f+seep*.35f,.002f,.14f+seep*.45f);}
   for(int n=0;n<drift.Count;n++){var d=drift[n];d.gameObject.SetActive(watch.WaterHeight>.035f);var pos=d.position;pos.y=watch.WaterHeight+.015f+Mathf.Sin(Time.time*.6f+n)*.006f;d.position=pos;d.rotation=Quaternion.Euler(Mathf.Sin(Time.time+n)*3,n*67,Mathf.Cos(Time.time*.8f+n)*3);}
   if(Time.time>=nextRipple){nextRipple=Time.time+.18f;foreach(var t in contacts)if(t){var p=t.position;if(t==head)p.y-=1.6f;if(Mathf.Abs(p.y-watch.WaterHeight)<.10f&&new Vector2(p.x,p.z).magnitude<3.9f){Shader.SetGlobalVector("_KeeperRipple"+(ripple++%4),new Vector4(p.x,p.z,Time.time,.22f));break;}}}
   if(Time.time>=nextSplash&&Mathf.Sin(5.18f+Time.time*1.4f)>.85f){nextSplash=Time.time+Mathf.Lerp(18,7,severity);wash.volume=Mathf.Lerp(.05f,.15f,severity);if(wash.clip)wash.Play();if(spray)spray.Emit(24);}
  }
  void OnDestroy(){if(seepMaterial)Destroy(seepMaterial);if(jetMaterial)Destroy(jetMaterial);if(dropletMaterial)Destroy(dropletMaterial);if(flood)Destroy(flood);if(ocean)Destroy(ocean);if(seaMesh)Destroy(seaMesh);for(int i=0;i<4;i++)Shader.SetGlobalVector("_KeeperRipple"+i,Vector4.zero);}
 }
}
